using System.Globalization;
using System.Text;
using Dapper;
using Npgsql;
using Sigov.Application.Transito;
using Sigov.Infrastructure.Persistence.Dapper;

namespace Sigov.Infrastructure.Transito;
public sealed class TransitoRepository(DapperContext db):ITransitoRepository
{
 private sealed record Spec(string Table,string Code,string Description,string Status);
 private static readonly IReadOnlyDictionary<string,Spec> Specs=new Dictionary<string,Spec>(StringComparer.OrdinalIgnoreCase){
  ["Agentes"]=new("transito_agente","matricula","nome","status"),["Condutores"]=new("transito_condutor","cnh","nome","status"),["Veiculos"]=new("transito_veiculo","placa","modelo","status"),["Infracoes"]=new("transito_infracao_tipo","codigo","descricao","active"),["Autos"]=new("transito_auto_infracao","numero_auto","descricao","status"),["Notificacoes"]=new("transito_notificacao","numero_notificacao","destinatario_nome","status"),["Recursos"]=new("transito_recurso","protocolo_recurso","requerente_nome","status"),["Julgamentos"]=new("transito_julgamento","id::text","relator_nome","resultado"),["Ocorrencias"]=new("transito_ocorrencia","id::text","descricao","status"),["Sinalizacao"]=new("transito_sinalizacao","id::text","descricao","status"),["Intervencoes"]=new("transito_intervencao_viaria","id::text","titulo","status"),["Linhas"]=new("transito_linha_transporte","codigo","nome","status"),["Rotas"]=new("transito_rota_transporte","id::text","nome","status"),["Pontos"]=new("transito_parada_ponto","codigo","nome","status"),["Autorizacoes"]=new("transito_autorizacao_transporte","numero_autorizacao","titular_nome","status"),["Vistorias"]=new("transito_vistoria_transporte","id::text","itens_verificados","status"),["Credenciais"]=new("transito_credencial","numero_credencial","beneficiario_nome","status"),["Auditoria"]=new("transito_auditoria","id::text","acao","acao")};
 private static readonly IReadOnlyDictionary<string,HashSet<string>> AllowedFields=new Dictionary<string,HashSet<string>>(StringComparer.OrdinalIgnoreCase){
  ["Agentes"]=["cpf","telefone","email","cargo","data_inicio","data_fim","observacao"],["Condutores"]=["cpf","categoria_cnh","validade_cnh","telefone","email","endereco","observacao"],["Veiculos"]=["renavam","chassi","marca","ano_fabricacao","cor","proprietario_nome","proprietario_documento","tipo_veiculo","observacao"],["Infracoes"]=["gravidade","valor_multa","pontos","base_legal"],["Autos"]=["agente_id","condutor_id","veiculo_id","infracao_tipo_id","data_hora_infracao","local_infracao","latitude","longitude","condutor_identificado","justificativa_sem_condutor","justificativa_sem_veiculo","valor_multa","justificativa_cancelamento"],["Notificacoes"]=["auto_infracao_id","data_emissao","data_vencimento","meio_envio","destinatario_documento","endereco_envio","observacao"],["Recursos"]=["auto_infracao_id","notificacao_id","requerente_documento","data_recurso","fundamento"],["Julgamentos"]=["recurso_id","data_julgamento","fundamentacao"],["Ocorrencias"]=["tipo","data_hora","local","latitude","longitude","gravidade","agente_id","providencias"],["Sinalizacao"]=["tipo","local","latitude","longitude","estado_conservacao","data_instalacao","data_ultima_vistoria","observacao"],["Intervencoes"]=["tipo","local","data_inicio","data_fim_prevista","data_fim_real","responsavel","impacto","observacao"],["Linhas"]=["tipo_transporte","operador","observacao"],["Rotas"]=["linha_id","sentido","distancia_km","tempo_estimado_min","observacao"],["Pontos"]=["endereco","latitude","longitude","acessibilidade","observacao"],["Autorizacoes"]=["tipo","titular_documento","veiculo_id","linha_id","data_emissao","data_validade","justificativa_cancelamento","observacao"],["Vistorias"]=["autorizacao_id","veiculo_id","agente_id","data_vistoria","resultado","irregularidades","prazo_regularizacao"],["Credenciais"]=["tipo","beneficiario_documento","data_emissao","data_validade","justificativa_cancelamento","observacao"],["Auditoria"]=[]};
 public async Task<TransitoDashboard> DashboardAsync(TransitoContexto c,CancellationToken ct){using var cn=db.CreateConnection();const string q="""select (select count(*) from sigov.transito_auto_infracao where tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null and data_hora_infracao>=date_trunc('month',now())) AutosMes,(select count(*) from sigov.transito_auto_infracao where tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null and status in ('EMITIDO','PENDENTE')) AutosPendentes,(select count(*) from sigov.transito_notificacao where tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null and status<>'PAGA' and data_vencimento between current_date and current_date+7) NotificacoesVencendo,(select count(*) from sigov.transito_recurso r where r.tenant_id=@TenantId and r.entity_id=@EntityId and r.deleted_at is null and r.status='PENDENTE' and not exists(select 1 from sigov.transito_julgamento j where j.recurso_id=r.id and j.deleted_at is null)) RecursosPendentes,(select count(*) from sigov.transito_ocorrencia where tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null and status='ABERTA') OcorrenciasAbertas,(select count(*) from sigov.transito_sinalizacao where tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null and estado_conservacao in ('RUIM','MANUTENCAO')) SinalizacoesManutencao,(select count(*) from sigov.transito_autorizacao_transporte where tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null and data_validade<=current_date+30) AutorizacoesVencendo,(select count(*) from sigov.transito_vistoria_transporte where tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null and resultado='REPROVADA') VistoriasReprovadas,(select count(*) from sigov.transito_credencial where tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null and data_validade<=current_date+30) CredenciaisVencendo""";return await cn.QuerySingleAsync<TransitoDashboard>(new CommandDefinition(q,c,cancellationToken:ct));}
 public async Task<TransitoPagina> ListarAsync(TransitoContexto c,string recurso,TransitoFiltro f,CancellationToken ct){var s=SpecFor(recurso);using var cn=db.CreateConnection();var page=Math.Max(1,f.Pagina);var size=Math.Clamp(f.Tamanho,1,10000);var where=$"tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null and (@Busca is null or cast({s.Code} as text) ilike '%'||@Busca||'%' or cast({s.Description} as text) ilike '%'||@Busca||'%') and (@Status is null or cast({s.Status} as text)=@Status) and (@Inicio is null or created_at::date>=@Inicio) and (@Fim is null or created_at::date<=@Fim)";var p=new{c.TenantId,c.EntityId,f.Busca,f.Status,f.Inicio,f.Fim,Limit=size,Offset=(page-1)*size};var total=await cn.ExecuteScalarAsync<long>($"select count(*) from sigov.{s.Table} where {where}",p);var items=(await cn.QueryAsync<TransitoRegistro>($"select id,cast({s.Code} as text) Codigo,cast({s.Description} as text) Descricao,cast({s.Status} as text) Status,created_at CriadoEm from sigov.{s.Table} where {where} order by created_at desc limit @Limit offset @Offset",p)).AsList();return new(items,page,size,total);}
 public async Task<IReadOnlyList<TransitoOpcao>> OpcoesAsync(TransitoContexto c,string tipo,CancellationToken ct){var s=SpecFor(tipo);using var cn=db.CreateConnection();var label=tipo.ToUpperInvariant() switch {"AGENTES"=>"matricula||' — '||nome||' — CPF ***.***.***-'||right(regexp_replace(cpf,'\\D','','g'),2)","CONDUTORES"=>"nome||' — CPF ***.***.***-'||right(regexp_replace(cpf,'\\D','','g'),2)||' — CNH '||cnh","VEICULOS"=>"placa||' — '||modelo||' — '||proprietario_nome","INFRACOES"=>"codigo||' — '||descricao||' — '||gravidade","AUTOS"=>"numero_auto||' — '||left(descricao,80)","NOTIFICACOES"=>"numero_notificacao||' — '||destinatario_nome","RECURSOS"=>"protocolo_recurso||' — '||requerente_nome","LINHAS"=>"codigo||' — '||nome","PONTOS"=>"codigo||' — '||nome||' — '||endereco","AUTORIZACOES"=>"numero_autorizacao||' — '||titular_nome",_=>$"cast({s.Code} as text)||' — '||cast({s.Description} as text)"};return (await cn.QueryAsync<TransitoOpcao>($"select id,{label} Rotulo from sigov.{s.Table} where tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null order by 2 limit 500",c)).AsList();}
 public async Task<long> SalvarAsync(TransitoContexto c,string recurso,TransitoRegistroRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Codigo)||string.IsNullOrWhiteSpace(r.Descricao))throw new ArgumentException("Código e descrição são obrigatórios.");var s=SpecFor(recurso);var cols=new List<string>{"tenant_id","entity_id"};var names=new List<string>{"@TenantId","@EntityId"};var data=new DynamicParameters();data.Add("TenantId",c.TenantId);data.Add("EntityId",c.EntityId);if(!s.Code.Contains("::",StringComparison.Ordinal))Add(s.Code,r.Codigo);Add(s.Description,r.Descricao);if(s.Status!="active")Add(s.Status,r.Status);else Add("active",true);using var cn=db.CreateConnection();cn.Open();using var tx=cn.BeginTransaction();var allowed=AllowedFields[recurso];foreach(var (key,value) in r.Campos){if(!allowed.Contains(key))throw new ArgumentException($"Campo não permitido para {recurso}: {key}.");if(key.EndsWith("_id",StringComparison.Ordinal)&&long.TryParse(value,out var relatedId)){var related=RelationTable(key);var belongs=await cn.ExecuteScalarAsync<bool>(new CommandDefinition($"select exists(select 1 from sigov.{related} where id=@relatedId and tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null)",new{relatedId,c.TenantId,c.EntityId},tx,cancellationToken:ct));if(!belongs)throw new ArgumentException("O relacionamento selecionado não pertence ao contexto atual.");}Add(key,string.IsNullOrWhiteSpace(value)?null:value);}try{var id=await cn.ExecuteScalarAsync<long>(new CommandDefinition($"insert into sigov.{s.Table}({string.Join(',',cols)}) values({string.Join(',',names)}) returning id",data,tx));await cn.ExecuteAsync("insert into sigov.transito_auditoria(tenant_id,entity_id,tabela,registro_id,acao,usuario,dados_novos) values(@TenantId,@EntityId,@Tabela,@Id,'CRIAR',@Usuario,jsonb_build_object('codigo',@Codigo))",new{c.TenantId,c.EntityId,Tabela=s.Table,Id=id,c.Usuario,r.Codigo},tx);tx.Commit();return id;}catch(PostgresException ex){throw new ArgumentException("Dados inválidos ou relacionamento fora do contexto: "+ex.ConstraintName,ex);}void Add(string col,object? val){if(cols.Contains(col))return;cols.Add(col);var n="p"+cols.Count;names.Add("@"+n);data.Add(n,val);} }
 public async Task ExcluirAsync(TransitoContexto c,string recurso,long id,CancellationToken ct){var s=SpecFor(recurso);using var cn=db.CreateConnection();cn.Open();using var tx=cn.BeginTransaction();var n=await cn.ExecuteAsync(new CommandDefinition($"update sigov.{s.Table} set deleted_at=now() where id=@id and tenant_id=@TenantId and entity_id=@EntityId and deleted_at is null",new{id,c.TenantId,c.EntityId},tx,cancellationToken:ct));if(n==0)throw new KeyNotFoundException("Registro não encontrado neste contexto.");await cn.ExecuteAsync(new CommandDefinition("insert into sigov.transito_auditoria(tenant_id,entity_id,tabela,registro_id,acao,usuario) values(@TenantId,@EntityId,@Tabela,@id,'EXCLUIR',@Usuario)",new{c.TenantId,c.EntityId,Tabela=s.Table,id,c.Usuario},tx,cancellationToken:ct));tx.Commit();}
 public async Task<byte[]> CsvAsync(TransitoContexto c,string recurso,TransitoFiltro f,CancellationToken ct){string[] exportaveis=["Autos","Notificacoes","Recursos","Ocorrencias","Sinalizacao","Autorizacoes","Vistorias","Credenciais"];if(!exportaveis.Contains(recurso,StringComparer.OrdinalIgnoreCase))throw new ArgumentException("Relatório não permitido.");var p=await ListarAsync(c,recurso,f with{Pagina=1,Tamanho=10000},ct);var b=new StringBuilder("Código;Descrição;Status;Criado em\r\n");foreach(var x in p.Itens)b.AppendLine($"{Csv(x.Codigo)};{Csv(x.Descricao)};{Csv(x.Status)};{x.CriadoEm:O}");return new UTF8Encoding(true).GetBytes(b.ToString());}
 private static Spec SpecFor(string r)=>Specs.TryGetValue(r,out var s)?s:throw new ArgumentException("Recurso de trânsito inválido.");private static string RelationTable(string key)=>key switch{"agente_id"=>"transito_agente","condutor_id"=>"transito_condutor","veiculo_id"=>"transito_veiculo","infracao_tipo_id"=>"transito_infracao_tipo","auto_infracao_id"=>"transito_auto_infracao","notificacao_id"=>"transito_notificacao","recurso_id"=>"transito_recurso","linha_id"=>"transito_linha_transporte","ponto_id"=>"transito_parada_ponto","autorizacao_id"=>"transito_autorizacao_transporte","rota_id"=>"transito_rota_transporte",_=>throw new ArgumentException("Relacionamento não permitido.")};private static string Csv(string? v){var s=v??"";if(s.Length>0&&"=+-@".Contains(s[0]))s="'"+s;return '"'+s.Replace("\"","\"\"")+'"';}
}
